import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { formatFixed, formatFloat } from "../server/driver/pyfmt.ts";

// Generated by CPython 3.14: [x, repr(x), [format(x, ".Nf") for N in 0,1,2,3,6]]
const vectors = JSON.parse(
  readFileSync(
    new URL("./fixtures/pyfmt-vectors.json", import.meta.url),
    "utf8"
  )
) as [number, string, string[]][];

test("formatFloat matches Python repr()", () => {
  for (const [x, repr] of vectors)
    assert.equal(formatFloat(x), repr, String(x));
});

test("formatFixed matches Python fixed-point formatting", () => {
  for (const [x, , fixed] of vectors) {
    [0, 1, 2, 3, 6].forEach((d, i) =>
      assert.equal(formatFixed(x, d), fixed[i], `${x} .${d}f`)
    );
  }
});
